
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_b86_mgc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_b86_mgc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.318161306580028e+00, -4.236638813190041e+00, -4.122521003316441e+00, -3.964679379033317e+00, -3.750100986740646e+00, -3.465553883634925e+00, -3.101432672692411e+00, -2.658455515906370e+00, -2.155482606764312e+00, -1.627810978562369e+00, -1.100082819359862e+00, -7.123194915526548e-01, -6.034929314989866e-01, -5.040896924109809e-01, -3.738875050045017e-01, -2.463157042730867e-01, -1.395202335629613e-01, -6.072246532633910e-02, -1.913166129120933e-02, -4.189775637901212e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


